func_after:
SessionRestoreImpl(Profile* profile,
                   Browser* browser,
                   bool synchronous,
                   bool clobber_existing_tab,
                   bool always_create_tabbed_browser,
                   const std::vector<GURL>& urls_to_open)
    : profile_(profile),
      browser_(browser),
      synchronous_(synchronous),
